import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"API reference","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"API reference"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/"}]],"pageClass":"api-index","editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/tools/docs/site/api/index.md"}},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":0}`),a={name:`api/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API reference”">​</a></h1><p>The API reference for every package JSPrismarine publishes, generated from the TypeScript source and its doc comments. Pick a package for its classes, functions and types; <a href="/pr-preview/pr-2948/packages.html">Packages</a> has each one&#39;s README and npm page.</p><p>Every package is published under the <code>@jsprismarine</code> scope.</p><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to “Server”">​</a></h2><p>The server itself, its console and the kernel that wires its modules.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/prismarine/">prismarine</a></td><td>Dedicated Minecraft Bedrock Edition server written in TypeScript</td></tr><tr><td><a href="./@jsprismarine/server/">server</a></td><td>Minecraft: Bedrock Edition dedicated server entrypoint</td></tr><tr><td><a href="./@jsprismarine/console/">console</a></td><td>Terminal user interface for the JSPrismarine server console</td></tr><tr><td><a href="./@jsprismarine/console-protocol/">console-protocol</a></td><td>Message types and links between the JSPrismarine server and its console</td></tr><tr><td><a href="./@jsprismarine/kernel/">kernel</a></td><td>Module kernel: lifecycle, a token-keyed service registry, and the event bus that modules plug into</td></tr></tbody></table><h2 id="network-and-protocol" tabindex="-1">Network and protocol <a class="header-anchor" href="#network-and-protocol" aria-label="Permalink to “Network and protocol”">​</a></h2><p>Packets, transports and sign-in, for a server or a client.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/protocol/">protocol</a></td><td>Protocol package used by JSPrismarine packages</td></tr><tr><td><a href="./@jsprismarine/raknet/">raknet</a></td><td>Basic RakNet implementation written in TypeScript</td></tr><tr><td><a href="./@jsprismarine/nethernet/">nethernet</a></td><td>NetherNet, the WebRTC transport of Minecraft: Bedrock Edition: signaling, identities and LAN discovery</td></tr><tr><td><a href="./@jsprismarine/auth/">auth</a></td><td>Minecraft: Bedrock Edition login identity, for both ends: offline and Xbox Live providers for a client, and login verification for a server</td></tr><tr><td><a href="./@jsprismarine/client/">client</a></td><td>Minecraft: Bedrock Edition client</td></tr><tr><td><a href="./@jsprismarine/binaryutils/">binaryutils</a></td><td>Basic binary data managing tool written in TypeScript.</td></tr></tbody></table><h2 id="world" tabindex="-1">World <a class="header-anchor" href="#world" aria-label="Permalink to “World”">​</a></h2><p>Terrain, decoration, light, storage and the systems that tick a world.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/worldgen/">worldgen</a></td><td>Java Edition terrain generation: randoms, noise, density functions, aquifers and chunk sampling</td></tr><tr><td><a href="./@jsprismarine/chunkgen/">chunkgen</a></td><td>Java Edition&#39;s chunk generation ladder: the ten statuses, the step table that declares what each one may read and write, and the holders and worker pool that run them</td></tr><tr><td><a href="./@jsprismarine/features/">features</a></td><td>Java Edition world decoration: feature types, block state and value providers, placement modifiers and the seeded placement pipeline</td></tr><tr><td><a href="./@jsprismarine/structures/">structures</a></td><td>Structure templates: the Java and Bedrock template readers, placement transforms, processors and jigsaw assembly</td></tr><tr><td><a href="./@jsprismarine/lighting/">lighting</a></td><td>Server-internal block light and sky light engine for Bedrock worlds</td></tr><tr><td><a href="./@jsprismarine/leveldb/">leveldb</a></td><td>LevelDB reader/writer for Minecraft: Bedrock Edition worlds, in pure TypeScript</td></tr><tr><td><a href="./@jsprismarine/engine-systems/">engine-systems</a></td><td>Shared world-system primitives for scheduling, redstone signals, random ticks, explosions, and weather.</td></tr><tr><td><a href="./@jsprismarine/spawning/">spawning</a></td><td>Bedrock spawn rules: the 24-component grammar, the condition evaluator, population pools and the spawn loop.</td></tr></tbody></table><h2 id="gameplay" tabindex="-1">Gameplay <a class="header-anchor" href="#gameplay" aria-label="Permalink to “Gameplay”">​</a></h2><p>Blocks, items, entities, commands and the rules that make them vanilla.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/content/">content</a></td><td>The content runtime shared by every domain: registries, tags, components, behaviors, hook dispatch and load-time flattening</td></tr><tr><td><a href="./@jsprismarine/blocks/">blocks</a></td><td>The Bedrock block definition grammar, component runtime, permutation evaluation, state model and the jsprismarine_vanilla overlay pack</td></tr><tr><td><a href="./@jsprismarine/block-behaviors/">block-behaviors</a></td><td>The vanilla block behavior families, written against the BlockHooks seam and a WorldActions world interface</td></tr><tr><td><a href="./@jsprismarine/items/">items</a></td><td>The item definition and component runtime: Java 26.3&#39;s 122 data component types over Bedrock item identities</td></tr><tr><td><a href="./@jsprismarine/item-behaviors/">item-behaviors</a></td><td>The vanilla item behavior families that fill the item hook seam, with Java&#39;s mining speed and attack damage formulas.</td></tr><tr><td><a href="./@jsprismarine/entities/">entities</a></td><td>The Bedrock entity runtime: definition parsing, components, component groups, the event engine, entity properties, filters and the goal scheduler</td></tr><tr><td><a href="./@jsprismarine/entity-brains/">entity-brains</a></td><td>Java Edition&#39;s brain AI: memories, sensors, activities, behavior combinators and the twenty mobs that build a brain</td></tr><tr><td><a href="./@jsprismarine/entity-goals/">entity-goals</a></td><td>The 170 vanilla Bedrock AI goals and the A* path finder they navigate with, written against the goal seam of @jsprismarine/entities</td></tr><tr><td><a href="./@jsprismarine/recipes/">recipes</a></td><td>The Java Edition recipe evaluator: all 22 recipe serializers, a crafting matcher, and a compile step to Bedrock identifiers</td></tr><tr><td><a href="./@jsprismarine/loot/">loot</a></td><td>Java Edition loot table evaluator: 9 entry types, weighted selection, random sequences and Bedrock translation.</td></tr><tr><td><a href="./@jsprismarine/enchantments/">enchantments</a></td><td>Java Edition enchantment definitions, effect components, the enchanting table and the anvil.</td></tr><tr><td><a href="./@jsprismarine/trading/">trading</a></td><td>Bedrock trade tables: the economy and legacy grammars, offer generation and the villager trading economy.</td></tr><tr><td><a href="./@jsprismarine/advancements/">advancements</a></td><td>Java Edition advancement engine: the 58 trigger types, the requirements grammar, per-player progress and reward hooks.</td></tr><tr><td><a href="./@jsprismarine/commands/">commands</a></td><td>Data-driven command layer: Mojang&#39;s Bedrock command table, a Java-shaped command tree, the Bedrock packet flattener and the selector grammars.</td></tr><tr><td><a href="./@jsprismarine/brigadier/">brigadier</a></td><td>A javascript re-implementation of Mojang&#39;s Brigadier library</td></tr><tr><td><a href="./@jsprismarine/mcfunction/">mcfunction</a></td><td>Java Edition mcfunction runtime: parser, macros, function tags and a queue-based executor</td></tr><tr><td><a href="./@jsprismarine/predicates/">predicates</a></td><td>Java Edition predicate, item modifier and value provider evaluator for loot, advancements and enchantments.</td></tr></tbody></table><h2 id="data-and-formats" tabindex="-1">Data and formats <a class="header-anchor" href="#data-and-formats" aria-label="Permalink to “Data and formats”">​</a></h2><p>Game data, identifiers, packs, Molang and the file formats they use.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/bedrock-data/">bedrock-data</a></td><td>Minecraft Bedrock game data exported in a nodejs friendly way.</td></tr><tr><td><a href="./@jsprismarine/minecraft/">minecraft</a></td><td>Minecraft: Bedrock Edition data and related utilities</td></tr><tr><td><a href="./@jsprismarine/mapping/">mapping</a></td><td>The Java Edition to Bedrock Edition identifier seam: generated mapping tables and a reviewed loss list</td></tr><tr><td><a href="./@jsprismarine/nbt/">nbt</a></td><td>Minecraft: Bedrock Edition NBT parser/writer</td></tr><tr><td><a href="./@jsprismarine/molang/">molang</a></td><td>Molang parser, compiler and evaluator for Bedrock behavior packs</td></tr><tr><td><a href="./@jsprismarine/packs/">packs</a></td><td>Bedrock pack stack loader: directories, .mcpack/.mcaddon archives and brarchive layers composed into per-registry definitions.</td></tr><tr><td><a href="./@jsprismarine/color-parser/">color-parser</a></td><td>Parse minecraft color codes</td></tr></tbody></table><h2 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to “Utilities”">​</a></h2><p>Errors, logging and math shared by the other packages.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./@jsprismarine/errors/">errors</a></td><td>JSPrismarine shared errors</td></tr><tr><td><a href="./@jsprismarine/logger/">logger</a></td><td>JSPrismarine logger and utilities</td></tr><tr><td><a href="./@jsprismarine/math/">math</a></td><td>JSPrismarine math utilities</td></tr></tbody></table>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};